code='''def transform(grid):
    g=[row[:] for row in grid]
    H,W=len(g),len(g[0]); bg=max(set(x for row in g for x in row), key=lambda x:sum(r.count(x) for r in g))
    # Find monochrome connected shapes; fill rectangular hollow frames, and mark the center of 3x3 hollow markers.
    seen=set()
    for r in range(H):
      for c in range(W):
        color=g[r][c]
        if color==bg or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); cells=[]
        while stack:
          y,x=stack.pop(); cells.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            q=(y+dy,x+dx)
            if 0<=q[0]<H and 0<=q[1]<W and q not in seen and g[q[0]][q[1]]==color:
              seen.add(q); stack.append(q)
        ys=[y for y,x in cells]; xs=[x for y,x in cells]; y0,y1=min(ys),max(ys); x0,x1=min(xs),max(xs)
        # A rectangular border component encloses a field colored 2.
        if y1-y0>=2 and x1-x0>=2 and len(cells)==2*(y1-y0)+2*(x1-x0):
          for y in range(y0+1,y1):
            for x in range(x0+1,x1): g[y][x]=2
        # The 3x3 symbols have a blank center; change it to 7.
        elif y1-y0==2 and x1-x0==2 and (y0+1,x0+1) not in cells:
          g[y0+1][x0+1]=7
    return g
'''
